const profiles = {};
const p = (route,title,shows,steps,value,limits='') => profiles['/en/dashboard'+route] = {title,shows,steps,value,limits};
const aliases = {
 '/inventory':'/inventory/items', '/inventory/items/new':'/inventory/items/create', '/items/new':'/inventory/items/create',
 '/cashDrawer':'/finance/cash-drawer', '/settings/organization':'/settings/company',
 '/purchases':'/purchase-orders', '/purchases/[id]':'/purchase-orders/[id]',
};
const shared = {
 '/items':'/inventory/items', '/settings/locations/new':'/settings/locations/create',
 '/finance/tax-rates/create':'/settings/tax-rates/create',
 '/suppliersSystem':'/purchases/suppliers', '/suppliersSystem/new':'/purchases/suppliers/create',
 '/suppliersSystem/[id]':'/purchases/suppliers/[id]', '/suppliersSystem/[id]/edit':'/purchases/suppliers/[id]/edit',
};
p('', 'Operations dashboard',
 `Sales, orders, customers, inventory value, average order value and collected-cash summaries; sales trends, top products, stock health, location performance, alerts, recent activity and pending actions.`,
 `Confirm the organization, then choose period and location. Read Overview first; open Inventory for stock questions or Operations for outstanding work. Use Refresh to fetch again and follow the relevant quick action or source record.`,
 `Start the day by identifying the largest change and the oldest actionable exception, then finish that workflow in its owning module.`,
 `Live data is a polling/read-model label, not a promise of instantaneous updates. The hook defaults to 30 days, marks data stale after 30 seconds and polls every 60 seconds while applicable; loading, errors and browser suspension can delay it. Read the metric notes before equating a card with a statutory account.`);
p('/daily-digest','Daily digest',
 `A dated brief of business signals, risks, priorities and evidence-linked recommendations for the current organization and accessible workspaces.`,
 `Read the generated time and evidence state. Open the source for a priority before acting. Generate brief or Retry requests a new brief; Prepare proposal opens the governed proposal flow. Accept proposal, Reject proposal and feedback choices record decisions.`,
 `Use a brief to choose a small number of evidence-supported actions for the day, then confirm their outcomes in the source page.`,
 `Generating, accepting, rejecting or rating a brief can persist records. An AI explanation does not itself approve a payment, post a journal or prove that an action is complete.`);
p('/owner-war-room','Owner war room',
 `Changes since yesterday, ranked risks, proof-linked actions, control status, module state, freshness and an acknowledgement trail. Critical, High and Redacted counts concern the returned briefing scope.`,
 `Check freshness and hidden/redacted notices. Open a risk, inspect its source or proof, and assign the real work through the responsible module. Acknowledge brief records that you reviewed the brief.`,
 `Compare unresolved high-impact risks across cash, stock and close evidence before prioritizing staff time.`,
 `Acknowledgement is a review record, not resolution. An upgrade prompt or catalogue badge is not evidence of purchased access or completed provisioning.`);
p('/manager-action-center','Manager action center',
 `A prioritized run sheet, business signals, open/critical/due/overdue work, proof links and scope notices. The implementation selects organization or assigned-location presentations according to access.`,
 `Confirm which locations you are responsible for. Work through Do first today, open source evidence, and route each issue to its owner. Inspect evidence before any reconciliation sign-off and use the required identity confirmation.`,
 `Convert an increasing overdue count into a list of specific records and handoffs instead of treating the summary as the work itself.`,
 `Location responsibility is not HR reporting-line authority. Some proof-only actions need a proof-drawer host; a route link may be available where an embedded drawer is not.`);
p('/manager-action-center/daily-close','Branch daily close',
 `Evidence coverage and checks for a selected location and business date, including supported, unsupported and incomplete checks and review/sign-off state.`,
 `Select location and business date, then Load close evidence. Inspect missing evidence in the source workspace. Start review records a review; Sign daily close requires the current password and the current evidence to satisfy the command rules.`,
 `Keep one review record for each location/day and resolve differences while the shift evidence is still easy to obtain.`,
 `A branch sign-off does not close the accounting period or automatically reconcile payments. Unsupported checks stay visible and must not be counted as passed.`);
p('/analytics','Business pulse',
 `Today, week and month sales signals, changes, risks, priorities and links into operational evidence. Command modes alter how the same available information is framed.`,
 `Read the stated period and generation time. Compare the change with the current value, open the source, and decide whether it needs an operational follow-up.`,
 `Use changes to detect a developing problem early; confirm its size using the appropriate detailed report.`,
 `Operational analytics is distinct from certified accounting-close evidence. Missing or redacted evidence limits the conclusion.`);
p('/analytics/referrals','Referral funnel',
 `Aggregate issued links, clicks, conversions and invite activations by source and campaign, including supported statement-delivery and accountant-invitation pathways.`,
 `Read the generated timestamp, compare funnel stages and inspect the source/campaign breakdown. This screen is an aggregate report; there is no campaign editor or recipient list here.`,
 `If issued links increase while activations stay flat, investigate the associated invitation or statement workflow before expanding distribution.`,
 `The reviewed read contract uses all-time aggregates; do not interpret these as a selected monthly campaign cohort. Recipient contacts, raw IP addresses and raw user agents are excluded from this reporting contract.`);
p('/analytics/reports','Reports',
 `Financial, cashier, item-performance and cash-flow report families, with provenance/freshness information where supplied. Item reporting includes revenue, quantity, profit and margin comparisons.`,
 `Choose the report type and period: 7 days, 30 days or This month where shown. Refresh after upstream updates. For item performance, search products and change Revenue, Quantity, Profit or Margin sorting; Show all products removes the narrow item focus. Read the report-trust banner before exporting or making decisions.`,
 `Compare like periods and scopes, then use the detailed product or cashier rows to identify which change explains the total.`,
 `A missing provenance banner or unavailable figure is not zero. Query aliases can choose a report family; they do not create additional dashboard pages. Some reports expose operational formulas rather than ledger reports.`);
p('/sales','Daily sales',
 `A reporting-day/location summary, recorded cash information, top items by recorded value and saved payment categories.`,
 `Set Reporting day and the available location. Use Refresh after transactions change. Read the recorded categories and open POS, customer orders or finance evidence for the underlying workflow.`,
 `Compare the recorded daily sales with shift and payment evidence before agreeing a day's operating result.`,
 `This route currently renders a reporting screen. It is not a general sales-order creation or fulfillment workbench. Recorded cash and payment categories do not establish bank settlement.`);
p('/inventory/items','Item directory',
 `Item identity, SKU, classification, pricing and available inventory indicators, with selection, row actions, search and filters.`,
 `Search by item/SKU and narrow the category/brand filters. Use Add Item to create, Edit for master data, or the row's supplier link for sourcing. Select rows deliberately before a selected export. Read the confirmation before Delete; preserve evidence for items already used in operations.`,
 `Use consistent SKU, classification and reorder settings to make stock searches and replenishment decisions reliable.`,
 `Metadata edits are not stock adjustments. Export and selection can be limited to loaded/selected rows; the export label and downloaded rows are the authority for scope.`);
p('/inventory/items/create','Create item',
 `A product setup wizard covering names/descriptions, identity, images, prices, classification, inventory policy and optional opening stock.`,
 `Enter the English name and the required image/product information. Review SKU/barcode, cost/selling/MSRP prices, unit, tax, category and brand; supply optional French text and physical details where useful. If using Add Opening Stock, select a location and enter an integer quantity of at least 1 and a nonnegative unit cost. Review the wizard before saving.`,
 `Create a usable item and, where appropriate, its evidenced starting quantity in the same controlled workflow.`,
 `Opening stock posts quantity; it is not a harmless form preference. Do not enter opening stock for receipts already recorded through purchasing. Exact live validation messages and upload availability were not exercised.`);
p('/inventory/items/[id]/edit','Edit item',
 `Existing item image, bilingual identity, SKU/barcode, physical details, prices/tax, classification, inventory thresholds and lifecycle/tracking options.`,
 `Open Edit from the directory. Change only the intended master fields; use the replacement-image control if needed. Review Track inventory, Active item, Discontinued, Serial number tracking, Batch tracking and Expiry tracking carefully, then save and reload the item.`,
 `Keep future transactions consistent while retaining the item's history and identity.`,
 `Tracking options only affect workflows that actually support the corresponding evidence. Editing an item's displayed cost or stock policy does not repair historical ledger quantities.`);
p('/inventory/items/[id]/suppliers','Item supplier relationships',
 `Suppliers linked to one item, preferred-supplier status, supplier SKU, lead time, minimum order quantity, unit cost, last purchase date and notes.`,
 `Use Add Suppliers to Item, search the available supplier list and select relationships. Choose a linked supplier to Edit Supplier Details. Review Preferred Supplier, Supplier SKU, Lead Time (days), Min Order Quantity and Unit Cost before saving. Discard changes closes an unsaved edit.`,
 `Compare lead time and supplier-specific cost before preparing a purchase order, especially when a preferred supplier cannot meet demand.`,
 `The available supplier lookup is bounded; an absent supplier may require directory/setup work or a broader lookup. Saved relationship terms are planning data, not a placed order or confirmed receipt.`);
p('/inventory/items/[id]/others','Item other-information placeholder',
 `A short placeholder sentence referencing the item ID.`,
 `Return to the item directory or use the item Suppliers page for actual supplier relationship management.`,
 `Avoid spending time looking for controls that are not implemented on this route.`,
 `Placeholder functionality: the source contains no complete other-information workflow. No browser verification was possible.`);
p('/inventory/brands','Brands',
 `A searchable brand directory with activity and item-usage filters, related-item counts and row actions.`,
 `Filter status and With Items/No Items as needed. Use Add Brand to create, View Items to inspect related products, Refresh to reload and Export for the available dataset. Edit the intended brand from its row.`,
 `Standardize brand names to avoid splitting product analysis across near-duplicate labels.`);
for(const [r,verb] of [['/inventory/brands/create','Create'],['/inventory/brands/[id]/edit','Edit']])p(r,verb+' brand',`English/French brand names and a logo URL in the brand form.`,`Enter or correct the name fields and optional image reference as indicated. Submit the ${verb.toLowerCase()} form, then verify the saved brand in the directory.`,`Keep product classification consistent across searches and reports.`,`This changes brand master data; it does not move stock or change past transactions.`);
p('/inventory/categories','Categories',`A product-category directory and hierarchy, activity filters, related items and category management actions.`,`Search and filter the directory. Open a category to inspect its hierarchy and linked items; use create/edit for classification changes.`,`Group inventory in ways that make stock and sales comparisons useful.`,`A filtered category list is not a stock valuation report.`);
for(const [r,verb] of [['/inventory/categories/create','Create'],['/inventory/categories/[id]/edit','Edit']])p(r,verb+' category',`English/French category names, image URL and parent-category selection.`,`Choose a clear name and the correct parent, review the hierarchy, then save. Return to the category detail to verify the result.`,`Avoid duplicate or misplaced categories that fragment reports.`,`The exact hierarchy validation/error messages require live confirmation; do not assume the UI permits cycles or self-parenting.`);
p('/inventory/categories/[id]','Category detail',`The selected category and its related classification information.`,`Use Back, View Items and Edit category to move between the category, its items and its form.`,`Inspect the impact of a category change before editing it.`);
p('/inventory/units','Units',`Unit names/symbols, types, base units, conversion rates and active/usage summaries.`,`Search or filter Type and Status. Open Create unit or Edit unit, enter English/French names, Symbol, Type, Base unit and Conversion rate as applicable, then save. Review Remove unit carefully when used by items.`,`Use consistent units and conversions so quantities mean the same thing in purchasing and inventory.`,`A conversion rate must be interpreted against the selected base unit. This page does not prove that every downstream workflow automatically converts arbitrary unit combinations.`);
p('/inventory/units/create','Create unit',`The Units dashboard with its create form opened.`,`Complete the unit identity and conversion fields described in Units, save, and verify the new row.`,`Create the right measurement unit before creating products.`);
p('/inventory/units/[id]/edit','Edit unit',`The Units dashboard with the selected unit in edit mode.`,`Review existing usage and the base-unit relationship before saving changes.`,`Prevent inconsistent quantities caused by casually changing a shared unit.`);
p('/inventory/transfers','Location transfers',`Transfer route, status, priority, items, creator/date, status mix and route summary, plus a create dialog and detail/timeline views.`,`Filter status, source, destination and Search transfers. Create Location Transfer requires distinct source/destination locations and item quantities; review priority, requested date and notes. Open the saved transfer and follow only the next actions allowed by its current status.`,`Move stock with a documented source, destination and status trail rather than changing item quantities manually.`,`Creation is a request/draft stage. Treat approval, dispatch and receipt as separate events; see the detailed control notes for implemented buttons and limits.`);
p('/inventory/movements','Inventory movement history',`Quantity/value movements with business identity, item, type, source, reference, actor, batch/expiry, corrections, proof and notes.`,`Use date/search/source filters to find the affected item and location. Open the movement detail and trace its source record before deciding on a correction.`,`Explain why stock changed and distinguish purchase receipts, sales, transfers and governed corrections.`,`History is evidence, not a form for overwriting old stock. A correction should remain linked to its originating workflow.`);
p('/inventory/loss-control','Inventory loss control',`Read-only loss summaries, breakdowns and recent-loss rows, with completeness/provenance, filters and a selected-record detail drawer.`,`Set dates and relevant filters; reset filters if no results match. Open a loss row, read its source and evidence state, then resolve any underlying process issue in its owning workflow. Retry after a loading failure.`,`Investigate repeated item/location losses and compare their recorded value before changing procedures.`,`The screen is analytical: it does not itself approve write-offs or edit valuation. Partial source coverage must remain visible in any conclusion.`);
p('/customers','Customers',`Customer identity, activity, order/debt indicators, language and directory summaries with row actions.`,`Search and use active/inactive, open-order, unpaid, over-limit or order-history filters. Create a customer or open View analytics, Edit, Create statement or Archive from the chosen row. Export only the scope and fields you intend to share.`,`Turn the unpaid/over-limit segments into a focused collection queue and keep inactive customers out of new operations.`,`Directory balance/order indicators are operational and may differ in scope from a dated statement or the posted ledger.`);
for(const [r,verb] of [['/customers/new','Create'],['/customers/[id]/edit','Edit']])p(r,verb+' customer',`Customer name/code, email/phone, address, tax identity, payment terms, credit limit, preferred language, active state and notes.`,`Complete required identity fields, validate contact details and review terms/credit limit before saving. Check the saved profile and active status afterward.`,`Accurate terms and contacts improve statements, follow-up and credit decisions.`,`Inactive preserves history while restricting future use. Contact fields alone do not authorize sending messages or sharing financial records.`);
p('/customers/[id]','Customer profile',`A single customer's identity, commercial activity and order/payment-related summaries with quick actions.`,`Verify the customer identity, then choose View orders, Create statement, Edit or Open sales. Send email and Call hand off to the configured communication application where present; Export summary produces the available profile summary.`,`Understand the relationship before changing terms or chasing a balance.`,`This is record-specific information. A profile summary is not necessarily a full date-bounded account statement.`);
p('/customers/[id]/orders','Customer orders',`Sales orders associated with the selected customer and customer quick actions.`,`Use available table presentation controls to find an order. Open its available details and compare status/payment information; return to View profile or Create statement for the account view.`,`Separate individual order issues from the customer's total exposure.`,`The current /sales destination is a daily-sales report, so an Open sales link should not be described as a complete order editor.`);
p('/customers/[id]/statement','Customer statement',`A period-based customer statement and governed sharing/delivery controls.`,`Set the period and currency as offered, prepare the statement and inspect its entries. Review recipient/channel, consent and dispute/promise options before any protected share/delivery action. Confirm success in the returned statement/delivery state.`,`Share a consistent statement snapshot and tie collection follow-up to specific supporting entries.`,`Preparing a statement, creating a secure share and delivering it are distinct actions. Email/WhatsApp delivery is consequential; exact supported states and inputs are in the detailed control notes.`);
p('/purchase-orders','Purchase orders',`A purchase-order workbench with status/date/search filters, selected rows, exports and record actions.`,`Find the supplier/order, inspect its status, then create a new order or open the existing detail. Use the status-appropriate approval, receiving, cancellation or print action; confirm each transition in the refreshed record.`,`Maintain one traceable order-to-receipt flow for purchasing and inventory teams.`,`Approval is not receipt, and a purchase order is not a supplier invoice or settlement. Legacy /purchases links lead here.`);
p('/purchase-orders/new','Create purchase order',`A multi-step purchase form: supplier/location, order identity/dates, item lines and quantities/prices/tax, delivery/payment information and notes.`,`Select a valid supplier and receiving location, add the intended items, inspect quantities and unit costs, then progress through the review steps before saving. Reopen the saved order and check its status/total.`,`Agree the purchasing intent before goods arrive and reduce untracked receipts.`,`A saved draft does not send an order or post accounts. A cloned order must be reviewed as a new transaction; old dates and prices are not automatically still appropriate.`);
p('/purchase-orders/[id]/edit','Edit purchase order',`An editable order form for an eligible order, with item lines, review steps and unsaved-change handling.`,`Open an eligible record; edit the supplier/order fields and line quantities/prices. Use Previous/Continue to review, then save. If interrupted, use the offered discard/reopen workflow and inspect the saved record.`,`Correct a draft before approval or receiving creates downstream commitments.`,`State changes can make an open edit stale. Reload and review if the order has been received or otherwise advanced; do not force the old draft over current evidence.`);
p('/purchase-orders/[id]','Purchase order detail',`Order identity, supplier, lines, totals, status, receipt progress and next-stage actions.`,`Inspect the order, then Submit or Approve where permitted. Receive Items opens line quantities and receipt evidence: batch/lot, optional expiry and inspection disposition. Receive All Available fills remaining amounts; Clear All resets the receipt selection. Confirm receiving, then verify received/outstanding quantities.`,`Compare ordered and received quantities while retaining inspection evidence for inventory and payables.`,`Passed inspection releases through the supported flow; Failed or Incomplete inspection holds the received stock as implemented. Print is a document output, not supplier delivery or payment.`);
p('/purchase-orders/[id]/supplier-acknowledgement','Supplier acknowledgement',`The supplier-facing acknowledgement/share state and audit history for one purchase order.`,`Read the order and recipient reference, prepare the available secure acknowledgement workflow, and inspect its resulting status. Use revocation only when the share should cease to be usable.`,`Keep evidence of what the supplier was asked to acknowledge and whether the acknowledgement arrived.`,`A prepared or sent request is not a supplier acceptance. Sharing/delivery and revocation can write records or send data; do not confuse them with preview.`);
p('/purchase-orders/analytics','Purchase analytics',`Purchasing summaries and charts for selected dates/filters, with supporting purchase data.`,`Choose the reporting period, compare totals and supplier/order patterns, then return to Purchase orders for the records driving a change.`,`Plan purchasing using actual order activity while separating commitments from receipts and payments.`,`Read displayed coverage/freshness; operational order amounts should not be treated as posted purchasing expense without the accounting bridge.`);
p('/purchases/payables','AP control workbench',`Supplier-invoice readiness, matching and controlled accounts-payable work, including exceptions and evidence.`,`Find the invoice/work item, inspect its purchase order and receipt links, and resolve missing or mismatched evidence before using an offered approval/post/payment action. Confirm the resulting state and source links.`,`Prevent a supplier invoice from advancing without the required receipt, matching and approval evidence.`,`This workflow is separate from the finance Payables balance list. Use the detailed control notes for the actual actions exposed by the current workbench.`);
p('/purchases/payables/history','AP history',`Accounts-payable events, records and proof in a history workbench.`,`Narrow period/search/filter scope, select a record and inspect its details and lineage. Open the source AP workbench to perform a permitted next step.`,`Explain an invoice/payment movement and preserve its evidence trail.`,`Filtered history is not necessarily the organization's full current payable balance.`);
p('/purchases/suppliers','Supplier directory',`Supplier contacts, terms, activity, open-order/credit/linked-item indicators, filters and management actions.`,`Search and filter active, open orders, over limit, linked items or no links. Create/edit/open the intended supplier. For export, inspect whether Include sensitive fields is available and selected, then verify the output scope.`,`Keep supplier identity and item links usable for purchasing and avoid duplicate payee records.`,`Archiving preserves existing history; sensitive export fields have additional permission constraints.`);
for(const [r,kind] of [['/purchases/suppliers/create','Create'],['/purchases/suppliers/[id]/edit','Edit'],['/purchases/suppliers/[id]','View']])p(r,kind+' supplier',`The supplier directory opens the appropriate ${kind.toLowerCase()} dialog for the current route. Forms cover name/code, contact information, address/tax identity and commercial terms.`,`Confirm supplier identity. ${kind==='View'?'Inspect details and follow the available edit/order/item links.':'Complete required identity fields, review terms and active status, save, and verify the returned supplier row.'}`,`Use a single supplier master record across sourcing, purchase orders and AP.`,`These are route-driven modes of the same dashboard, not independent supplier data stores.`);
p('/pos','Point of sale',`Location/terminal setup, shift state, customer, catalog in grid/list form, cart lines, totals, split tenders, receipt-related fields and offline-sync status.`,`Choose location and terminal, then open a shift with the actual Opening float. Scan barcode or search SKU, item or category; add items and review quantities and customer. Enter tender amounts and any provider-authorized payment transaction ID required for electronic tender. Commit only after checking payment evidence. At shift end enter Counted cash and a Variance explanation when required, close the shift and inspect the resulting session record.`,`Tie each sale to stock, a cashier session and accountable payment evidence.`,`Some controls are incomplete: Park sale and Manager override show a backend-gated warning. Current sale commit sends receipt channel NONE even though delivery fields are rendered. Do not promise immediate email/WhatsApp delivery from this checkout. See POS control notes.`);
p('/finance/cash-drawer','Cash drawer management',`Overview, Drawers, Movement, Sessions and Journal views, with location/date filters, balances, sessions and variance information.`,`Choose location/dates and Refresh. Search sessions by cashier/terminal and sort by Time, Sales or Variance. Expand session/journal details, then follow Open POS, Reconciliation, Manage terminals, Cash flow or Cash and payment history to the owning workflow.`,`Use unexplained variance to identify the specific shift requiring a count/evidence review.`,`A cash drawer is physical cash accountability; it is not a bank balance. A current balance and a dated session total can have different time bases.`);
const financeViews={
 '':'Finance overview', '/analytics':'Finance analytics', '/cash-flow':'Cash flow', '/costs':'Costs',
 '/profit-loss':'Profit and loss overview', '/profitability':'Profitability', '/retail':'Retail finance', '/sales':'Sales finance'
};
for(const [suffix,title] of Object.entries(financeViews))p('/finance'+suffix,title,
 `A selected view of the shared Finance command center: operating revenue/purchasing/expense/payment signals and related charts/tables. The route determines the initial view.`,
 `Set location and Today, Yesterday, 7 days, 30 days, month/quarter/year-to-date or Custom period as available. Read period and currency, then Refresh. Open the relevant payments, receivables, payables or source record to explain a change.`,
 `Compare operating performance on a consistent scope, and use source records or posted-accounting reports to confirm a financial conclusion.`,
 `These are capped operational read models with mixed period/current-balance scopes. The displayed profit calculation subtracts purchases, expenses and refunds from revenue; it is not conventional ledger gross profit. Finance collected payments can include PENDING records. See the metric dictionary.`);
p('/finance/payments','Payments',`A specialized payment ledger surface with payment status/method/date/search filters, sorting, density, pagination and links to operational evidence.`,`Choose the period and available filters; distinguish PENDING, PAID and CANCELLED records. Open the relevant receipt/order/history or reconciliation link and check the source evidence.`,`Separate outstanding payment records from evidence that money actually settled.`,`A saved payment status alone does not establish a matched bank/provider transaction. Check whether totals cover the filtered/current page or another server summary.`);
p('/finance/receivables','Receivables',`Customer open-balance and collection-related rows in a specialized ledger view.`,`Search and filter the customer/work items, inspect status/age and open history or the customer statement for dated evidence.`,`Prioritize collection by amount, age and supporting documents.`,`Current customer balance can differ from a historical statement; finance overview customer summaries also have an active/top-record cap.`);
p('/finance/payables','Payables',`Supplier payable balances and supporting commercial rows in a specialized finance surface.`,`Find the supplier and inspect its outstanding evidence; use the AP workbench and AP history links for matching/readiness information.`,`Identify the largest supplier obligations and avoid confusing an order commitment with an approved invoice.`,`This balance view is separate from the read-only AP control workbench. It does not prove a complete invoice-to-payment command UI exists.`);
p('/finance/cash-payment-history','Cash and payment history',`Cash/payment events with timeline/source context, record details and evidence status.`,`Narrow dates, search and offered filters; use 25/50/100 page-size options where displayed. Open the selected record and its source/proof before making a correction elsewhere.`,`Explain when cash/payment evidence changed and which transaction produced it.`,`An event-history filter is not a recalculation of every financial balance. No direct history overwrite is implied.`);
p('/finance/receivables/history','Receivables history',`Customer open-item and receivable evidence in a history workbench.`,`Find the customer/reference and period, then inspect the selected event, amount, status and source link. Return to the customer/receivables workspace for next steps.`,`Resolve statement questions with specific dated evidence.`,`Historical events, outstanding items and current balance are different views and may not share the same totals.`);
p('/finance/cash-command','Cash command',`A cash-trust overview combining payment/reconciliation/suspense/drawer/close signals, changes since yesterday, risks and prioritized evidence-linked actions.`,`Read freshness and scope. Open proof on a supported record or navigate to the source workspace. Change command mode only to change presentation; verify actions at the source.`,`Follow the most material cash uncertainty through to its evidence instead of relying on a single total.`,`Proof visibility is role-filtered. An unavailable proof drawer or source does not establish that the underlying financial record is absent.`);
p('/finance/stock-to-cash','Stock-to-cash flow',`A chain from purchasing and stock through sales, cash, reconciliation, ledger and close, showing available risks and proof.`,`Inspect each stage and follow a flagged source. Use Open proof where supported; purchasing/stock stages may offer route navigation instead.`,`Locate the handoff where evidence stopped progressing—for example goods received but invoice/ledger proof still missing.`,`Stock and purchase-order steps remain route-only for some proof interactions. A chain visualization is not proof that every producer is fully integrated.`);
p('/finance/reconciliation','Payment reconciliation',`Statement/provider entries, payment matches, differences and suspense, with location/date controls, run/sign/export and governed matching commands.`,`Set location and dates and Refresh. Prepare a supported CSV with amount and date plus any available reference, direction, fee and currency; inspect import errors. Run the offered reconciliation, review proposed matches and suspense, and use the independent approval/identity flow only after checking current evidence. Sign and Export only when the relevant gates permit.`,`Turn unmatched money into assigned, evidenced work and preserve the link between operational payments and external settlement.`,`Import, Run, Sign, Assign, Propose match and Approve match can write records. Replacing stale evidence requires a fresh review; a manual reference cannot establish provider payment authority.`);
p('/accounting','Accounting ledger',`Accounting access/setup status, accounts, open periods, draft/posted-entry counts and recent journal activity.`,`Check readiness first. Open Setup or Control center for blockers, Journals for drafts/posted entries, and Reports for the posted-accounting view.`,`Use one consistent entry point for posting discipline and ledger reporting.`,`Draft entries and operational reports are not posted financial statements.`);
p('/accounting/setup','Ledger setup',`Country pack/base currency/fiscal-year settings, default journals, fiscal years, periods and readiness state.`,`Review Country pack, Base currency and fiscal start month/day, then Save settings if authorized. Create fiscal year with name/start/end dates; Ensure defaults prepares default journals. Review blockers before Mark ready. Close period is consequential and must follow the intended close process.`,`Set accounting foundations before posting transactions so dates, journals and currency are consistent.`,`Mark ready is setup state, not professional certification. Creating a fiscal year generates periods; closing a period changes posting eligibility.`);
p('/accounting/accounts','Accounting accounts',`Account code, bilingual name, SYSCOHADA class/type, normal balance, currency, mapping and manual/control-account properties; active/archived rows.`,`For Create account enter code/class/names/type, DEBIT or CREDIT normal balance and currency; review mapping and manual-post/control-account options. Use leaf accounts for manual entries. Archive only the intended account and verify the list afterward.`,`Keep posting destinations and financial-statement classifications understandable and reviewable.`,`An account code or class is not evidence that a country's statutory mapping has been professionally validated.`);
p('/accounting/journals','Journal entries',`Draft and posted/reversed entry lists, entry summaries and protected Post and Reverse actions.`,`Open a draft and check its journal/date/accounts and balanced debit/credit lines. Post only when ready and allowed. Reverse a posted entry with the required reason and control checks; verify the reversal trail rather than deleting history.`,`Maintain a clear distinction between prepared entries and ledger evidence.`,`Posting and reversal affect the ledger. A reversed entry remains part of the audit trail; read reports using their documented posted/reversal treatment.`);
p('/accounting/journals/new','New journal entry',`A manual journal form with postable account lookups, journal, date, currency, reference, memo and debit/credit lines.`,`Wait for account/journal lookups to load successfully. Select an open-period date and suitable manual journal, enter balanced lines on postable leaf accounts, review reference/memo and Create draft. Verify the saved draft in Journals before a separate posting action.`,`Capture a supported manual accounting entry with a review point before posting.`,`Lookup failure is a blocker to entry, not an empty valid account list. Stopping new manual journals can block creation while leaving historical entries visible.`);
p('/accounting/control-center','Accounting control center',`Setup blockers, account mappings, journals, posting rules, periods, business-event outbox and sensitive-control status.`,`Refresh readiness, read each blocker and open the relevant setup/source workflow. Review permission, risk and fresh-auth requirements before Lock accounting setup.`,`Resolve missing accounting foundations and delivery problems before relying on automated posting.`,`A lock is a protected configuration change; it does not retroactively prove every transaction posted correctly.`);
p('/accounting/reports/trial-balance','Trial balance',`Ledger-derived account debit/credit activity, balances and a balance check, with account code/name/type/normal balance rows.`,`Search or filter accounts, sort the table and change page/density as needed. Compare activity debit and credit; clear table filters when checking the complete report.`,`Find a specific account without losing sight of the full-report balance check.`,`Top report totals remain full-report totals when the local account table is filtered. This report is based on posted/reversed journal evidence, not sales-order totals.`);
p('/accounting/reports/financial-statements','Financial statements',`Posted-ledger profit and loss, management EBITDA bridge, net income, balance sheet, account drill-down and classification-review items.`,`Choose period/view and Apply period. Inspect the performance bridge and balance check; expand a statement line to its contributing accounts. Review classification warnings before relying on a subtotal.`,`Explain performance and position with a traceable account breakdown.`,`Management EBITDA is explicitly a management measure, not a statutory subtotal. Its bridge adds income tax, finance costs, depreciation and amortization to net income; unresolved classifications require accounting review.`);
for(const r of ['/accounting/close','/accounting/close/[periodId]'])p(r,'Close and assurance'+(r.includes('[')?' — selected period':''),`Period close readiness, critical blockers/findings, evidence coverage/provenance/graph, accountant review and deterministic close-pack export.`,`Choose/confirm the period and Refresh or Run assessment. Inspect each finding; Assign to me, add a source-linked comment or request a justified waiver where permitted. Record Ready to close or Changes requested in the accountant review. Export draft JSON while unresolved; use Export certified JSON only when its independent gates pass.`,`Keep period-end decisions tied to explicit evidence and unresolved exceptions.`,`Assignment, comment, waiver, review and assessment are persisted workflow actions. A waiver is separately reviewed; certified export and actual period closure are separate controls. Missing domains remain unavailable evidence.`);
p('/accounting/accountant-access','Accountant access',`Explicit accountant mandates with role, effective dates, expiry, consent evidence and revocation.`,`Enter Accountant email, firm identity, read-only/reviewer/preparer role, effective/expiry dates and consent-evidence hash, then review before Invite or grant access. Revoke only the intended mandate and confirm its new state.`,`Give an external accountant appropriate, time-bounded access to evidence.`,`A mandate is sensitive access and may send an invitation. A role title alone does not bypass tenant or command permissions.`);
p('/accounting/accountant-portal','Accountant portal',`Trust level, posted entries, source coverage, blockers, posted figures, evidence modules, recent links and audit trail.`,`Refresh evidence, inspect blockers and source links, then use Export trust pack when its gate permits. If figures are withheld, resolve critical data-trust blockers first.`,`Prepare a reviewable accounting evidence package instead of collecting disconnected screenshots.`,`Critical trust blockers can suppress financial figures. No figure is better than treating unavailable evidence as zero.`);
p('/accounting/accountant-portfolio','Accountant client portfolio',`Only clients with active, unexpired consent mandates, with links to their ledger evidence.`,`Choose a client you are authorized to review and Open ledger evidence. If no clients appear, check mandate scope/expiry with the granting organization.`,`Navigate client work without mixing organizations or assuming access to every tenant.`,`An empty portfolio can reflect access/expiry rather than absence of client accounting records.`);
p('/people','People directory',`Employee identity/readiness rows with search, sorting, date filters, pagination and links to profile, history and approvals.`,`Narrow to the intended employee or date range, read readiness/state and Open profile. Use Approvals for governed changes and History to trace applied changes.`,`Resolve source-data gaps before they reach payroll.`,`The returned data is scoped and may be redacted. A directory count is not necessarily all employees in every location.`);
p('/people/[employeeId]','Employee profile',`Employment identity, department/job/cost center/country/location/dates/user mapping and named readiness blockers.`,`Confirm the employee and responsibility scope. Read blockers such as missing active contract, contract evidence, frozen attendance or payment-destination evidence. Route each blocker to HR/payroll ownership; return to People for the next record.`,`Use a single profile to identify which upstream requirement prevents payroll readiness.`,`This profile is read-only. Location responsibility is expressly different from reporting-line authority; outside-scope profiles are denied, not empty.`);
p('/people/me','My employee workspace',`Self-service employee information plus leave, overtime and attendance-correction requests and payslip navigation.`,`Choose the request type, enter required dates/minutes/reason and Submit request. Check its returned/pending state; use Payslips for issued personal documents.`,`Provide the required time evidence early enough for manager review and payroll preparation.`,`Submitting a request is not approval or a frozen payroll input. Self-service does not expose all employees' pay.`);
p('/people/team','Team workspace',`Employees/requests within the manager's permitted responsibility and operational-time approval controls.`,`Inspect the scoped request and supporting dates/minutes/reason. Approve or Reject only the intended item with required justification, then verify the resulting state.`,`Clear pending time requests before the payroll input cut-off.`,`Manager responsibility and separation rules still apply; being able to view a request does not guarantee the right to approve it.`);
p('/people/approvals','People approvals',`Lifecycle, contract, document, compensation, salary and payment-destination requests grouped by review/apply stage and readiness.`,`Filter All, Review or Apply and the relevant domain. Open an item, inspect evidence, enter the decision reason and required evidence hash, then Approve, Reject or Apply as offered. Verify the new stage and history.`,`Keep request, independent decision and application separate and traceable.`,`The requester cannot review their own request; the approver/requester may also be barred from applying it. A separate operator must finish application when the service requires it.`);
p('/people/history','People movement history',`Recorded HR changes with domains, risk/proof filters and employee links.`,`Search/filter the movement and inspect supporting proof. Open profile to compare the current employee state with the recorded change.`,`Explain who changed employment-related data and why a payroll input changed.`,`History is a review surface, not permission to overwrite prior records.`);
p('/payroll','Payroll command center',`Run/payment/declaration/close readiness, action board, blockers, provider/authority health and specialist country-pack/pilot certification controls.`,`Start with current-period blockers and open the owning source workspace. Use source employees, contracts, compensation and attendance to understand readiness; go to Runs for permitted transitions. Specialist pack/pilot controls need reviewed references, versions, evidence and independent approvals.`,`Track one payroll period across preparation, approval, payment and proof without assuming a green summary completes all stages.`,`Evaluate pack, Record certificate, Approve certificate and pilot persistence create governance records; they do not confer legal certification by their presence in the UI.`);
p('/payroll/employees','Payroll employee sources',`Linked/unmapped users, active-contract and frozen-attendance readiness, candidates, orphan source rows and redactions.`,`Search the employee and inspect each readiness column. Follow the linked People profile/source ownership to correct the named gap before calculating.`,`Stop missing identity links from becoming missing or duplicated pay.`,`This is a source/readiness workbench; no complete employee-creation form is exposed here.`);
p('/payroll/contracts','Payroll contract readiness',`Contracts and linked users with eligibility, status, evidence and redaction indicators.`,`Find the employee/contract, verify the effective period and evidence, then use the supported People approval/source process for outstanding changes.`,`Confirm the contract governing a payroll input before calculation.`,`The current screen is read-only; its lifecycle title does not imply full contract-authoring controls.`);
p('/payroll/compensation','Compensation readiness',`Rubrique catalogue, compensation assignments and salary-change queue with requested/approved and redacted states.`,`Inspect the relevant assignment and salary-change stage; complete a pending review/application through People approvals when available.`,`Avoid calculating from a proposed salary as though it were effective compensation.`,`The reviewed workbench reports source state; it does not expose a complete salary/assignment creation form.`);
p('/payroll/attendance','Attendance and payment readiness',`Attendance completeness and approved/pending/missing payment destinations, with blockers, redaction and proof controls.`,`Find the employee/period, read the blocker and inspect proof. Resolve source requests/approvals and payment-destination evidence through their owning process before payroll advances.`,`Prevent rejected payments and incomplete time inputs at the end of the run.`,`An approved request is distinct from the frozen attendance snapshot consumed by payroll.`);
p('/payroll/runs','Payroll runs',`Runs with period, state, readiness/proof, accounting links and a service-provided list of next actions.`,`Open the eligible action drawer: calculation, review, approval, emission or posting. Inspect required permission, Fresh auth, Maker-checker and source proof. Supply the requested evidence/date inputs and confirm the action; verify the resulting run state. Use separate declaration/payment drawers for those downstream stages.`,`Advance payroll through reviewable checkpoints instead of treating Calculate as completion.`,`Payment request, approval and release use separate actors where required. Release is a controlled batch transition, not proof the bank settled it; settlement evidence belongs in Payments.`);
p('/payroll/register','Payroll register tie-out',`Run lines, employee counts, net payable, payslips, payment allocations and ledger/close evidence with hashes/source links.`,`Compare the register with issued payslips and payment/accounting proof; inspect missing links before accepting the reconciliation.`,`Detect an amount or employee-scope mismatch before close.`,`A hash identifies evidence; it does not by itself prove independent review or external settlement. The page is primarily an evidence/tie-out surface.`);
p('/payroll/payments','Payroll payments and settlement evidence',`Employee balance/recovery cases and payment-batch reconciliation proof. The page combines two workspaces.`,`For a genuine balance settlement, enter amount/date, responsible identity, evidence/document hashes, reference and notes in Record settlement. For batch reconciliation, use Record settlement proof with the source register and supported provider/statement/match references, then inspect the returned state.`,`Connect released payroll amounts to traceable settlement evidence and distinguish partial from complete settlement.`,`These forms record protected evidence/state changes. They should not be described as an unrestricted bank-transfer initiation form; a manual reference is insufficient proof.`);
p('/payroll/declarations','Payroll declarations',`Prepared declaration rows, status, source-register proof, blockers, scope/redaction and adapter execution controls.`,`Inspect the declaration's locked-register source and readiness. Use Queue adapter execution only when the supported adapter and required evidence are ready, then track later execution and response evidence.`,`Keep statutory preparation and delivery work tied to the same payroll source.`,`Queued execution is not authority acceptance. External credentials, adapter capability, country-pack review and response evidence may still block completion.`);
p('/payroll/payslips','My payslips',`Issued payslips available to the current employee, with permitted lines, proof and blockers.`,`Choose the intended period/document and inspect available proof. If no payslip appears, check whether emission completed and your employee-user mapping is correct.`,`Give employees a consistent issued record without exposing other employees' compensation.`,`An approved run is not yet an issued payslip; self-service redaction and identity scope still apply.`);
p('/payroll/setup','Payroll setup and proof controls',`Payroll setup/readiness and specialist historical proof-backfill plans, dry-run results, certificates and approval/execution fields.`,`Review missing prerequisites with the payroll administrator. For specialist backfill work, inspect the dry-run/certificate and independent approval evidence before the protected Persist certificate, Approve execution, Validate proof or Execute backfill actions.`,`Expose historical proof gaps before a payroll rollout or assurance review.`,`This is not a simple everyday payroll-preferences screen. Hashes, approval-token evidence and idempotency fields require the documented operational process; never invent values to clear a blocker.`);
p('/compliance','Compliance center',`Country/status views of fiscal documents, certification state, open submissions, exceptions, active adapters and source/credential/review readiness.`,`Filter All countries/status, search the relevant document/submission queue and Refresh or Retry. Inspect the required country-pack/capability/credential/specification/reviewer evidence before assuming an adapter can submit.`,`Identify why a document is still waiting and send that precise gap to the responsible team.`,`The current dashboard principally monitors queues. It is not a universal tax-filing form; an active adapter badge is not proof of production authorization or authority acceptance.`);
p('/assurance/control-tower','Assurance control tower',`Open/blocking/overdue/hidden incidents, severity/workflow queues, engine runs, pending alerts and failures.`,`Open an incident's Detail or Source. Acknowledge records review; use Assign, Resolve, Suppress, Request waiver, Approve waiver or Reopen only when the action is allowed and its required reason/evidence is ready.`,`Assign control failures to named owners and distinguish silence/acknowledgement from actual resolution.`,`Suppression and waiver are controlled state changes, not correction of the underlying financial or operational record.`);
p('/assurance/control-tower/incidents/[incidentId]','Assurance incident detail',`One incident's source, severity, status, ownership, timeline, waivers and redacted evidence.`,`Inspect the source and timeline, choose the applicable action, supply owner/role/due date, reason/note/evidence or suppression/expiry dates as required, then Apply action. Verify the new timeline entry and status.`,`Maintain an accountable history of how an exception was handled.`,`A user who can see a summary may not be allowed to see all proof or approve a waiver.`);
p('/settings/company','Company settings',`The active organization record, operational/commercial summary and setup links. Summary counts appear above a full-width paid-revenue amount in the requested layout.`, `Confirm the organization identity. Open its settings form to review editable organization data. Use the displayed comparison/review flow before saving; resolve stale revisions with Load latest comparison. Registration/sign-in handoff controls open the appropriate external page for another organization. The reviewed CSV flow prepares scope before protected download.`, `Keep currency and organization identity consistent for downstream operations and use setup links to complete missing foundations.`, `The directory is scoped to the active organization, not unrestricted cross-tenant administration. Total records/Active records/Users/Paid revenue have different meanings; paid revenue is not proof of profit or bank settlement. Current exact metric scope is in the detailed notes.`);
p('/settings/modules','Module control center',`Foundation, package/composition and individual-module state, selection/dependencies, operational readiness/stops and review/identity controls.`,`Start with the active foundation and package composition. Inspect module dependencies and readiness; select only the capabilities your workflows need. Review the complete proposed change and confirm identity before applying any protected selection or operational command. Reload the server result and inspect what is selected, granted, provisioned and usable.`,`Keep the workspace aligned with actual operating needs and discover the specific access/setup blocker when a module is unavailable.`,`Selection, commercial grant, provisioning, operational availability and user permission are separate conditions. This page is not a checkout/payment form and does not automatically grant user permissions. Some stop controls are supported only for specific modules/workflows; see the module-control notes.`);
p('/settings/data-onboarding','Data onboarding',`A governed master-data import workbench for customers, suppliers and items, with template, dry validation, approval, commit and evidence.`,`Choose the target and Download template. Prepare a CSV within 5 MB and 1,000 rows. Run dry validation, inspect mapped fields/errors/risks and correct the file. Record the explicit approval for the exact source/mapping evidence, then Commit through the domain owners when allowed. Export the evidence manifest and inspect created results.`,`Onboard consistent master data with reviewable validation before operational use.`,`Dry validation may persist a run/evidence record. Zero validation errors is not permission to skip approval; a changed file or mapping needs fresh review. Do not treat this as a transaction/ledger import.`);
p('/settings/locations','Locations',`Locations with type, manager, address/contact, active/setup indicators, filters and links to stock, transfers, POS and drawers.`,`Search/filter by status, type, setup or date; set visible columns/density and select rows for export as needed. Create or edit a location, review default/approval/negative-stock settings and save. Follow inventory/POS links to complete operational setup.`,`Make stock and cash responsibility explicit by location.`,`Changing approval/default/negative-stock policy affects future behavior; location creation alone does not create a usable POS terminal or open shift.`);
p('/settings/locations/create','Create location',`The location dashboard with the create dialog, including name/code/type, manager, address/contact and policy options.`,`Enter required identity and intended manager/type, review policy checkboxes, save and confirm the new row before configuring its terminal or inventory.`,`Create a clear physical/operational scope before recording movements and sales.`);
p('/settings/locations/[id]/edit','Edit location',`The selected location in the shared management form.`,`Review identity, responsibility and operational policy changes, then save. Confirm the current record and downstream setup links.`,`Keep locations accurate without confusing an administrative edit with moving stock.`);
p('/settings/terminals','Terminals',`Terminal identity/number, location, assigned cashier, cash-drawer/session links, filters and active state.`,`Create or Edit a terminal, choosing location and valid cashier/drawer where required; review its generated/entered number. Use Open POS or drawer links to inspect operation. Deactivate only after checking live session consequences.`,`Give each checkout a traceable location, operator and drawer context.`,`A terminal record does not open a shift or establish payment-provider authority.`);
p('/settings/tax-rates','Tax rates',`Configured tax names, rates, types and activity with create/edit/remove controls and list presentation filters.`,`Find the intended tax. Create/Edit with bilingual names, type, percentage and active state; review before saving and verify the row. Inspect use/confirmation before Remove.`,`Apply consistent configured rates to supported product/order calculations.`,`A configured percentage is application data, not tax-law advice or proof the rate is legally correct for a country/product/date.`);
p('/settings/tax-rates/create','Create tax rate',`The tax-rate dashboard with its create dialog.`,`Enter name/type/rate and active state, validate the percentage field and save. Verify the new rate before assigning it to an item or transaction.`,`Prepare a reviewed rate before operational users need it.`);
p('/settings/tax-rates/[id]/edit','Edit tax rate',`The selected tax rate in the shared management form.`,`Review the intended name/type/rate/activity changes and save. Confirm the result and consider affected future uses.`,`Keep tax master data deliberate and consistent.`,`Changing a configuration does not imply automatic recalculation of historical transactions.`);
p('/settings/users','Users and invitations',`The organization member directory plus reviewed invitation form/history, pending/sent states and role choices.`,`Inspect current members before inviting. Enter the required recipient/name/role and reason, review the exact invitation and confirm identity when required. Check the returned receipt/history; Refresh invitations and Load older inspect server state. Open a member's access editor for role changes.`,`Add the right person with the right access while preserving an invitation trail.`,`An invitation is not an accepted membership. An uncertain submission result must be checked in history before resending; this workflow can send email.`);
p('/settings/users/update/[id]','Member access',`A selected member's current/proposed role assignments, review differences, identity confirmation and command history.`,`Select intended roles, review changes and reasons, confirm identity and submit the protected access change. Reload history/current membership to verify the result; resolve stale comparisons before retrying.`,`Keep access changes accountable and appropriately scoped.`,`Viewing a member does not grant authority to change every role. Self-access and last-custodian safeguards may block a change; this is not a general personal-profile editor.`);
p('/settings/roles','Role administration',`Roles and their permission-related summaries, search/selection and create/edit navigation.`,`Search for an existing role before Add Role. Open it to inspect its permission set and review process. Verify saved role changes from the directory/history.`,`Use reusable roles rather than ad hoc access assumptions.`,`A role name is not a guarantee of its permissions; assess its actual grant set and your authority to change it.`);
for(const [r,verb] of [['/settings/roles/new','Create'],['/settings/roles/update/[id]','Edit']])p(r,verb+' role',`English/French names, description, reviewed permission/risk catalogue, proposed changes, identity confirmation and history.`,`Enter the role's purpose, select only required permissions, inspect risk and any disabled/out-of-authority grants, then review and confirm the protected command. Check server history and the resulting role.`,`Build comprehensible access bundles with evidence of who changed them.`,`Uneditable grants may need to remain preserved. A local checkbox selection is not a saved permission change.`);
p('/settings/security','Security settings',`Password/credential readiness, session counts, recent login/security indicators, role/permission context and links to password maintenance.`,`Inspect current session and account state. Change password opens the dedicated form. Sign out other sessions revokes the other sessions; confirm their removal afterward.`,`Review active access and remove sessions that should no longer be valid.`,`The current page does not supply a finished MFA enrolment/challenge flow. A two-factor readiness label or navigation description should not be presented as an available toggle.`);
p('/change-password','Change password',`Current, new and confirm-password fields with password policy/error handling.`,`Enter the current password and a matching new/confirmation value that meets the displayed policy; submit only when ready and follow the sign-in/success instructions.`,`Replace an account credential through its supported protected workflow.`,`The source enforces strength/history/breach-related checks; a rejected password is not a transport failure to repeatedly resubmit. This documentation inspection did not change credentials.`);
p('/settings/appearance','Appearance',`Light, Dark and System theme choices and the resolved appearance.`,`Choose the desired theme. System follows the device preference; inspect the result in this browser.`,`Use a comfortable, readable theme for long work sessions.`,`This is a browser-persisted theme setting. There is no complete saved custom-palette, layout-preset or global-density settings model on this page; individual tables can have their own density controls.`);
p('/settings/notifications','Notification settings and tests',`Sound preference, a temporary notification queue and test controls.`,`Toggle sound as desired. Send test, Security alert and Payment update add synthetic notifications for presentation testing. Mark all read changes queue state; Clear queue removes the local list.`,`Check how alerts appear and sound before relying on the interface during operations.`,`Only the sound preference persists in browser storage; the queue is session memory. These are not real security events/payments and do not establish a durable email/push-subscription preference center.`);
p('/notifications-demo','Notification demonstration',`A notification test surface with synthetic notification actions.`,`Use only for deliberate presentation testing; return to operational evidence pages for real alerts and transactions.`,`Understand notification presentation without mistaking demonstrations for business records.`,`Demonstration functionality. Test buttons can change the local notification queue; they are not evidence of a production event pipeline.`);
// The AP surface exposes evidence, not invoice mutation commands.
profiles['/en/dashboard/purchases/payables'].steps = `Filter/search the invoice and payment-readiness rows, inspect match state and source evidence, and follow supported source links. Give the named exception to the responsible purchasing/AP operator through the organization's existing process.`;
profiles['/en/dashboard/purchases/payables'].limits = `The action queue is explicitly read-only in the current workbench. It does not expose a complete invoice match/approve/post/payment command flow; missing command UI must not be invented from service names.`;
profiles['/en/dashboard/purchases/payables'].steps = `Inspect recent invoices, released payments, pending bank changes and the read-only action queue. Use Open AP history, Open suppliers, Review history or a supplier-profile link to inspect supporting evidence. Reload the page for a fresh snapshot; there are no local search/date filters on this screen.`;
Object.assign(profiles['/en/dashboard/inventory/transfers'],{
 steps:`Filter status/source/destination and Search transfers. Create Location Transfer records the source, destination and item quantities. A different authorized user opens the DRAFT transfer and chooses Approve Transfer when allowed. In the current implementation that action posts the stock movement and completes the transfer immediately; verify both locations and movement history.`,
 limits:`There are no separate dispatch/receive buttons in this current workflow. Older status badges do not establish those operations. Priority and internal notes are collected in the form but omitted by the create action's service payload, so do not rely on them being saved.`
});
Object.assign(profiles['/en/dashboard/pos'],{
 shows:`Location/terminal setup, shift state, customer, catalog in grid/list form, cart quantities/totals, cash tender, receipt history controls and offline-sync status.`,
 steps:`Choose location and terminal, open a shift with the actual Opening float, then scan barcode or search SKU/item/category. Add items, confirm quantities and customer, enter the cash tender and review the sale before committing. At shift end enter Counted cash and a Variance explanation when required; close the shift and inspect the session record.`,
 limits:`The current selectable tender/receipt arrays expose CASH and NONE only: cash checkout with no delivery receipt. Electronic tender and email/SMS/WhatsApp branches exist in source but are not offered by this configuration. Park sale and Manager override only show a backend-gated warning. Do not describe those as working sale-management actions.`
});
Object.assign(profiles['/en/dashboard/finance/cash-payment-history'],{
 steps:`Use the type/lane, method/status and date filters; choose page size and open row details. Inspect generation, recorded-through and effective-as-of times and return to the source workspace for permitted corrections.`,
 limits:`The visible Search input is not applied by this source path. Export prepares authorization and a ready state but does not generate/download a CSV. The drawer explicitly marks proof unavailable. Use type/date filters and source evidence; do not expect those unfinished controls to complete the task.`
});
Object.assign(profiles['/en/dashboard/settings/company'],{
 shows:`The active organization record, relation counts, setup links and three count cards above a full-width Gross paid payment total.`,
 limits:`The current amount label is Gross paid payment total. It adds all non-deleted PAID payments, including both sales and purchases, across all dates before refund deductions. It is neither revenue nor cash balance. Relation counts do not filter each relation for active/deleted state. Currency is read-only in this form; this directory exposes the current organization only.`
});
Object.assign(profiles['/en/dashboard/settings/users'],{
 steps:`Search/filter members, inspect activation/verification/roles and switch Users/Invitations tabs. Invite user opens Email address and an authorized Role; Record invitation persists the reviewed request. Inspect its receipt/history and Refresh invitations before retrying an uncertain result. Replace invitation and Cancel invitation require their own review; use member access for an accepted invitation.`,
 limits:`Email delivery is disabled in the reviewed build. Recording an invitation or delivery request is not sending email. Verification, activation, accepted invitation and effective permissions are separate states. Deactivation is a protected action that revokes sessions and pending links while retaining business history; self/last-administrator safeguards apply.`
});
Object.assign(profiles['/en/dashboard/purchase-orders/[id]/supplier-acknowledgement'],{
 steps:`Issue the secure acknowledgement link using the required recipient reference and expiry inputs, then copy/share it through an authorized communication process. Inspect supplier responses and review any proposal. Revoke a link only when it should stop being usable.`,
 limits:`This workbench issues/copies a link; it has no send-email action. Actions require purchase-order update authority and identity verified within five minutes, but no inline password step-up form is exposed here. Buyer acceptance records a review decision without changing the authoritative PO, stock, AP or ledger.`
});
Object.assign(profiles['/en/dashboard/customers/[id]/statement'],{
 steps:`Set the period and currency, supply the current password and Generate immutable statement. Inspect its entries. For Queue secure delivery choose the channel/destination, confirm consent and review dispute/promise options, then inspect returned delivery evidence.`,
 limits:`Both commands require accounting export authority and fresh identity. Generating the snapshot and queuing delivery are separate writes. A queued delivery is not confirmed recipient delivery. Despite descriptive revocation wording, no revoke control is wired on this dashboard form.`
});
module.exports={profiles,p,aliases,shared};
// Page-specific outcomes avoid treating local controls and read-only workspaces as commands.
Object.assign(profiles['/en/dashboard/purchase-orders/[id]/supplier-acknowledgement'],{steps:`For an approved PO, review the optional recipient reference, choose Issue invitation, then Copy link. Inspect the generated expiry. Review proposals and use the permitted buyer decision or revocation command with its required reason.`,outcome:`Inspect token status/expiry, access history or the recorded buyer decision. This page does not change receipt quantities or stock.`});
Object.assign(profiles['/en/dashboard/purchases/payables'],{outcome:`Inspect refreshed invoice/payment/blocker evidence and follow the owning workflow.`,value:`Identify missing receipt, matching or approval evidence and give the responsible operator a specific case to resolve.`});
Object.assign(profiles['/en/dashboard/finance/cash-drawer'],{prerequisites:`An accessible location and relevant cash-drawer/session read authority. Viewing evidence does not require an active shift or sellable stock.`,outcome:`Check the refreshed session/drawer/variance evidence. Charge and Close take place through the separate POS workflow.`});
Object.assign(profiles['/en/dashboard/customers/[id]/statement'],{steps:`Select dates, confirm the read-only organization currency, provide the current password and Generate immutable statement. Inspect statement number/version, closing balance, open-item count, timestamps, hash and any truncation warning. For Queue secure delivery, review channel/destination, consent, dispute/promise options and password confirmation, then inspect returned queue evidence.`,shows:`A period-based immutable statement summary and governed delivery controls. There is no statement-entry table on this form.`});
Object.assign(profiles['/en/dashboard/analytics/reports'],{steps:`Choose Financial Summary, Cashier Performance, Item Performance or Cash Flow and inspect the selected dates. Changing report/date reloads it; use Retry after failure or reload the page after upstream changes. For Item Performance, search and change Revenue, Quantity, Profit or Margin sorting and use Show all products where offered. Read provenance before making decisions.`,limits:`No export/download control exists on the reviewed report screen. Location comes from URL/context, not a visible picker. Date shortcuts can include different endpoints than their informal names suggest; use the metric dictionary and inspect the actual range.`});
Object.assign(profiles['/en/dashboard/sales'],{shows:`A reporting-day/location summary that prefers a stored daily report, including its recorded cash/tender categories and draft/finalized state. Without a stored report it shows order aggregates and top items while cash/tender facts remain unavailable.`});
profiles['/en/dashboard/settings/users'].shows=`Organization member counts, activation/verification/role filters and an invitation register with Awaiting acceptance, Accepted, Expired and Cancelled states. Delivery-attempt history is separate.`;
profiles['/en/dashboard/settings/appearance'].outcome=`Inspect the active Light/Dark/System theme and its browser-persisted preference; no server command receipt is involved.`;
profiles['/en/dashboard/settings/modules'].outcome=`Compare Requested revision and Active workspace revision, inspect preparation conditions and the recorded change history, and verify whether the intended workspace is actually active.`;
profiles['/en/dashboard/change-password'].outcome=`Follow the returned success/sign-in instructions and confirm that the new credential works through normal sign-in. A rejected form is not a completed password change.`;
for(const route of ['/en/dashboard/settings/notifications','/en/dashboard/notifications-demo'])profiles[route].outcome=`Inspect the visible notification/read-count state in the current session. Reloading can clear the queue; only the sound preference persists in browser storage.`;
